export function catalogModel(id: string): CatalogModel { const model = CATALOG.find(model => model.id === id); if (!model) throw new Error("Modelo fora do catálogo aprovado"); return model; }
export const catalogFiles = (model: CatalogModel): CatalogFile[] => model.parts ?? [{file:model.file,bytes:model.bytes,sha256:model.sha256}];
export const modelUrl = (model: CatalogModel, file: CatalogFile = model) => `https://huggingface.co/${model.repo}/resolve/${model.revision}/${file.path ?? file.file}`;
